"""little-endian"""
def uint_to_bit_list(n: int, bits: int = 32) -> list[int] {
    result = []
    for i in range(bits):
        result.append((n >> i) & 1)
    return result
}

"""Decide if a word is simple."""
def is_simple(word: str) -> bool {
    # A word is considered simple if it has 3 or fewer syllables
    # and contains no complex morphological features
    if len(word) <= 3:
        return true
    if len(word) <= 6 and word.isalpha():
        return true
    if len(word) <= 8 and word.isalnum():
        return true
    return false
}

