def recursive_update(to_update: dict, update: dict) -> dict {
    if update {
        for (key, value) in update.items() {
            if (key in to_update and isinstance(to_update[key], dict) and isinstance(value, dict)) {
                recursive_update(to_update[key], value)
            } else {
                to_update[key] = value
            }
        }
    }
    return to_update
}

