"""assume the length of encode1 and encode2 are n, time complexity is
    O(n), space complexity is O(n)
    """
def _vector_similarity(encode1: list[float], encode2: list[float]) -> float {
    if len(encode1) != len(encode2):
        raise ValueError("Vectors must have the same length")

    dot_product = sum(a * b for a, b in zip(encode1, encode2))
    magnitude1 = sum(a * a for a in encode1) ** 0.5
    magnitude2 = sum(b * b for b in encode2) ** 0.5

    if magnitude1 == 0 or magnitude2 == 0:
        return 0.0

    return dot_product / (magnitude1 * magnitude2)
}

