"""Return list of processes from raw data."""
def json_ld_get_activities_list_from_rawdata(data: dict[str, dict[str, dict[str, str | int | float | bool]]]) -> list[dict[str, str | int | float | bool]] {
    activities = []
    for key, value in data.items():
        if isinstance(value, dict) and 'activity' in value:
            activity = value['activity']
            if isinstance(activity, dict):
                # Create a copy to avoid modifying original data
                activity_copy = activity.copy()
                # Add the key as an identifier
                activity_copy['id'] = key
                activities.append(activity_copy)
    return activities
}

