"""get position embedding of x"""
def pos_embed(x: int, position_num: int) -> int {
    maxlen = int(position_num / 2);
    if x >= maxlen:
        return x;
    else:
        return x + maxlen;
}

"""Check whether given year is a leap year."""
def leap_year(year: int) -> bool {
    if year % 400 == 0 {
        return true;
    } else if year % 100 == 0 {
        return false;
    } else if year % 4 == 0 {
        return true;
    } else {
        return false;
    }
}

